protected void testPrecision_3_oe(final String listEntry, final CalendarUnit expectedPrecision) {
        final FTPFile file = getParser().parseFTPEntry(listEntry);
        // removed other assertion
        final Calendar stamp = file.getTimestamp();
        // removed other assertion
        final int ordinal = expectedPrecision.ordinal();
        final CalendarUnit[] values = CalendarUnit.values();
        // Check expected unit and all more significant ones are set
        // This is needed for FTPFile.toFormattedString() to work correctly
        for(int i = ordinal; i < values.length; i++) {
            final CalendarUnit unit = values[i];
            assertTrue("Expected set "+unit+" in "+listEntry, stamp.isSet(unit.unit));
}
}

protected void testPrecision_4_oe(final String listEntry, final CalendarUnit expectedPrecision) {
        final FTPFile file = getParser().parseFTPEntry(listEntry);
        // removed other assertion
        final Calendar stamp = file.getTimestamp();
        // removed other assertion
        final int ordinal = expectedPrecision.ordinal();
        final CalendarUnit[] values = CalendarUnit.values();
        // Check expected unit and all more significant ones are set
        // This is needed for FTPFile.toFormattedString() to work correctly
        for(int i = ordinal; i < values.length; i++) {
            final CalendarUnit unit = values[i];
            // removed other assertion
        }
        // Check previous entry (if any) is not set
        // This is also needed for FTPFile.toFormattedString() to work correctly
        if (ordinal > 0) {
            final CalendarUnit prevUnit = values[ordinal-1];
            assertFalse("Expected not set "+prevUnit+" in "+listEntry, stamp.isSet(prevUnit.unit));
}
}

private void checkShortParse_1_oe(final String msg, final Calendar servertime, final Calendar input, final Calendar expected, final boolean lenient)
            throws ParseException {
        final FTPTimestampParserImpl parser = new FTPTimestampParserImpl();
        parser.setLenientFutureDates(lenient);
        final SimpleDateFormat shortFormat = parser.getRecentDateFormat(); // It's expecting this format

        final String shortDate = shortFormat.format(input.getTime());
        final Calendar output=parser.parseTimestamp(shortDate, servertime);
        final int outyear = output.get(Calendar.YEAR);
        final int outdom = output.get(Calendar.DAY_OF_MONTH);
        final int outmon = output.get(Calendar.MONTH);
        final int inyear = expected.get(Calendar.YEAR);
        final int indom = expected.get(Calendar.DAY_OF_MONTH);
        final int inmon = expected.get(Calendar.MONTH);
        if (indom != outdom || inmon != outmon || inyear != outyear){
            final Format longFormat = new SimpleDateFormat("yyyy-MM-dd hh:mm");
            fail("Test: '"+msg+"' Server="+longFormat.format(servertime.getTime())+". Failed to parse "+shortDate +(lenient ? "(lenient)" : "(non-lenient)")+" using " + shortFormat.toPattern()+". Actual "+longFormat.format(output.getTime())+". Expected "+longFormat.format(expected.getTime()));
